"""Generated byte-level controls only; no CHB-MIT payloads or model runs."""
from __future__ import annotations
import hashlib
import importlib.util
import os
from pathlib import Path
import struct
import tempfile
import unittest

ROOT = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location("edf_window", ROOT / "edf_window.py")
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)
WRITTEN = 0


def write(path, body):
    global WRITTEN
    path.write_bytes(body)
    WRITTEN += len(body)


def field(value, width):
    data = str(value).encode("ascii")
    assert len(data) <= width
    return data.ljust(width, b" ")


def generated(channels, *, records=2, reserved="", selected=None):
    """Each channel is a small independently specified digital signal fixture."""
    n = len(channels)
    fixed = (b"0       " + field("PRIVATE PATIENT", 80) + field("PRIVATE RECORD", 80) +
             b"01.01.0000.00.00" + field(256 + 256*n, 8) + field(reserved, 44) +
             field(records, 8) + field(1, 8) + field(n, 4))
    assert len(fixed) == 256
    fields = (("label", 16, "A-B"), ("transducer", 80, ""), ("unit", 8, "uV"),
              ("pmin", 8, -32768), ("pmax", 8, 32767), ("dmin", 8, -32768),
              ("dmax", 8, 32767), ("filter", 80, ""), ("rate", 8, 20),
              ("reserved", 32, ""))
    header = fixed + b"".join(field(c.get(key, default), width)
                               for key, width, default in fields for c in channels)
    payload = b""
    for rec in range(records):
        for c in channels:
            rate = c.get("rate", 20)
            values = c.get("values", list(range(rate * records)))
            payload += b"".join(struct.pack("<h", v) for v in values[rec*rate:(rec+1)*rate])
    body = header + payload
    selected = list(range(n)) if selected is None else selected
    rate = channels[selected[0]].get("rate", 20)
    row = {"recording_id": "PRIVATE SOURCE FILENAME", "biological_person": "PRIVATE PERSON",
           "edf_sha256": hashlib.sha256(body).hexdigest(),
           "edf_header_sha256": hashlib.sha256(header).hexdigest(),
           "native_sample_rate_hz": rate, "native_sample_count": records * rate,
           "observed_ticks": records * 10,
           "channels": [{"label": c.get("label", "A-B"), "role": c.get("role", "eeg")}
                        for c in channels], "predictor_channels": selected,
           "reference_intervals": [[1, 2]], "annotation_sha256": "f" * 64}
    return body, row


class WindowTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="generated-edf-", dir=ROOT)
        self.addCleanup(self.temp.cleanup)
        self.path = Path(self.temp.name) / "generated.edf"

    def reader(self, channels=None, *, body=None, row=None, **kwargs):
        if body is None:
            body, row = generated(channels or [{}])
        write(self.path, body)
        return m.RecordWindow(self.path, row, max_edf_bytes=len(body),
                              max_window_samples=kwargs.pop("max_window_samples", 1024),
                              max_output_values=kwargs.pop("max_output_values", 4096), **kwargs)

    def test_little_endian_signed_values_and_asymmetric_offset(self):
        values = [-257, 256] + [0] * 38
        with self.reader([{"values": values}]) as stream:
            self.assertEqual(stream.window(0, 2, available_through_tick=1)["channels"][0]["samples"], [-257., 256.])
        with self.reader([{"unit": "mV", "pmin": -1, "pmax": 3, "dmin": -10,
                           "dmax": 10, "values": [-10, 0, 10] + [0] * 37}]) as stream:
            self.assertEqual(stream.window(0, 3, available_through_tick=1)["channels"][0]["samples"], [-1000., 1000., 3000.])

    def test_negative_gain_is_not_rejected_or_reordered(self):
        with self.reader([{"pmin": 8, "pmax": -2, "dmin": -5, "dmax": 5,
                           "values": [-5, 0, 5] + [0] * 37}]) as stream:
            self.assertEqual(stream.window(0, 3, available_through_tick=1)["channels"][0]["samples"], [8., 3., -2.])

    def test_channel_major_record_layout_other_rate_and_duplicate_labels(self):
        body, row = generated([{"label": "A-B", "values": list(range(40))},
                               {"label": "OTHER", "role": "other", "rate": 3, "unit": "", "values": [9]*6},
                               {"label": "A-B", "values": [100+i for i in range(40)]}], selected=[2, 0])
        with self.reader(body=body, row=row) as stream:
            result = stream.window(19, 23, available_through_tick=12)
        self.assertEqual([x["channel_index"] for x in result["channels"]], [2, 0])
        self.assertEqual([x["label"] for x in result["channels"]], ["A-B", "A-B"])
        self.assertEqual([x["samples"] for x in result["channels"]], [[119., 120., 121., 122.], [19., 20., 21., 22.]])

    def test_256hz_exact_noninteger_and_integer_endpoint_rules(self):
        with self.reader([{"rate": 256}]) as stream:
            self.assertEqual(len(stream.window(0, 26, available_through_tick=1)["channels"][0]["samples"]), 26)
            with self.assertRaisesRegex(ValueError, "future"):
                stream.window(0, 27, available_through_tick=1)
            self.assertEqual(len(stream.window(0, 129, available_through_tick=5)["channels"][0]["samples"]), 129)
            with self.assertRaisesRegex(ValueError, "future"):
                stream.window(0, 130, available_through_tick=5)
            self.assertEqual(stream.window(511, 512, available_through_tick=20)["channels"][0]["samples"], [511.])

    def test_future_mutation_cannot_change_returned_prefix(self):
        body, row = generated([{"values": [1, 2, 3] + [9]*37}])
        with self.reader(body=body, row=row) as stream:
            first = stream.window(0, 3, available_through_tick=1)
        body, row = generated([{"values": [1, 2, 3] + [-700]*37}])
        with self.reader(body=body, row=row) as stream:
            second = stream.window(0, 3, available_through_tick=1)
        self.assertEqual(first, second)

    def test_annotation_and_other_channels_cannot_be_predictors(self):
        for channel in ({"role": "other"}, {"role": "annotation"},
                        {"label": "EDF Annotations", "role": "eeg"}, {"label": "-", "role": "eeg"}):
            with self.subTest(channel=channel), self.assertRaisesRegex(ValueError, "non-EEG"):
                self.reader([channel])

    def test_unknown_uncalibrated_and_malformed_calibrations_refuse(self):
        for change in ({"unit": ""}, {"unit": "mystery"}, {"pmin": "NaN"},
                       {"pmax": "1e9999"}, {"pmin": 1, "pmax": 1},
                       {"dmin": 4, "dmax": 4}, {"dmin": -32769}):
            with self.subTest(change=change), self.assertRaises(ValueError):
                self.reader([change])

    def test_declared_digital_range_is_checked_before_output(self):
        with self.reader([{"dmin": -5, "dmax": 5, "values": [6] + [0]*39}]) as stream:
            with self.assertRaisesRegex(ValueError, "digital extrema"):
                stream.window(0, 1, available_through_tick=1)

    def test_plus_clocks_are_explicitly_not_silently_flattened(self):
        for reserved in ("EDF+C", "EDF+D"):
            body, row = generated([{}], reserved=reserved)
            with self.subTest(reserved=reserved), self.assertRaises(ValueError):
                self.reader(body=body, row=row)

    def test_whole_file_identity_and_header_identity(self):
        body, row = generated([{}])
        corrupted = body[:-2] + struct.pack("<h", 990)
        with self.assertRaisesRegex(ValueError, "Complete admitted EDF hash"):
            self.reader(body=corrupted, row=row)
        row["edf_header_sha256"] = "0" * 64
        with self.assertRaisesRegex(ValueError, "Admitted header"):
            self.reader(body=body, row=row)

    def test_exact_geometry_and_admitted_native_support(self):
        body, row = generated([{}])
        for changed in (body[:-2], body + b"\x00\x00"):
            with self.subTest(size=len(changed)), self.assertRaises(ValueError):
                self.reader(body=changed, row=row)
        for field in ("native_sample_rate_hz", "native_sample_count", "observed_ticks"):
            changed = dict(row); changed[field] += 1
            with self.subTest(field=field), self.assertRaisesRegex(ValueError, "support differs"):
                self.reader(body=body, row=changed)

    def test_window_and_value_caps_never_truncate(self):
        with self.reader([{}], max_window_samples=2) as stream:
            with self.assertRaisesRegex(ValueError, "output budget"):
                stream.window(0, 3, available_through_tick=1)
        with self.reader([{}, {}], max_output_values=5) as stream:
            with self.assertRaisesRegex(ValueError, "output budget"):
                stream.window(0, 3, available_through_tick=1)
        body, row = generated([{}]); write(self.path, body)
        with self.assertRaises(ValueError):
            m.RecordWindow(self.path, row, max_edf_bytes=len(body)-1, max_window_samples=10, max_output_values=10)

    def test_public_window_contains_no_target_or_source_identity(self):
        with self.reader([{}]) as stream:
            result = stream.window(0, 3, available_through_tick=1)
        self.assertEqual(set(result), {"schema", "sample_start", "sample_stop", "sample_rate_hz", "available_through_tick", "channels"})
        for channel in result["channels"]:
            self.assertEqual(set(channel), {"channel_index", "label", "unit", "samples"})
        self.assertNotIn("PRIVATE", str(result))

    def test_changed_open_file_and_closed_handle_refuse(self):
        with self.reader([{}]) as stream:
            with self.path.open("r+b") as handle:
                handle.seek(-2, os.SEEK_END); handle.write(b"\x00\x00")
            global WRITTEN
            WRITTEN += 2
            with self.assertRaisesRegex(ValueError, "changed"):
                stream.window(0, 2, available_through_tick=1)
        with self.assertRaisesRegex(ValueError, "Closed"):
            stream.window(0, 2, available_through_tick=1)

    def test_pinned_dependency_cannot_be_replaced(self):
        altered = Path(self.temp.name) / "admission.py"
        write(altered, b"raise RuntimeError('must not execute')\n")
        with self.assertRaisesRegex(ValueError, "identity"):
            m.load_admission(altered)


if __name__ == "__main__":
    result = unittest.main(exit=False)
    print("GENERATED_FIXTURE_CUMULATIVE_WRITTEN_BYTES=" + str(WRITTEN))
    raise SystemExit(not result.result.wasSuccessful())
